B.aqr=new A.d("DELIL-0060",u.Y,"K\xe2inat kitab\u0131 ve f\u0131trat","\u0130badet Delili","\u0130nsan\u0131n ibadet ihtiyac\u0131, yarat\u0131l\u0131\u015f gayesine i\u015faret eder.","\u0130nsan sadece yemek, \xfcremek ve korunmakla tatmin olmaz; anlam, \u015f\xfck\xfcr, secde ve ba\u011fl\u0131l\u0131k ister. Bu ihtiya\xe7, insan\u0131n yaln\u0131z d\xfcnyaya g\xf6re de\u011fil, Allah\u2019a y\xf6neli\u015fe g\xf6re yarat\u0131ld\u0131\u011f\u0131 fikrini destekler.",B.FA,"orta",B.oN,B.aHY)
