B.aqQ=new A.d("DELIL-0068","F\u0131trat, Ahlak ve \u0130nsan Delilleri","\u0130\xe7 d\xfcnya ve toplum","Su\xe7luluk ve Tevbe","\u0130nsan yanl\u0131\u015f yapt\u0131\u011f\u0131nda yaln\u0131z topluma de\u011fil, a\u015fk\u0131n bir makama kar\u015f\u0131 mahcup olur.","Gizli g\xfcnah\u0131n bile vicdanda y\xfck b\u0131rakmas\u0131, insan\u0131n g\xf6r\xfcnmeyen bir \u015fahitlik ve hesap bilinci ta\u015f\u0131d\u0131\u011f\u0131n\u0131 d\xfc\u015f\xfcnd\xfcr\xfcr.",B.bt4,"orta",B.nb,B.aJu)
