B.amD=new A.d("DELIL-0076","F\u0131trat, Ahlak ve \u0130nsan Delilleri","\u0130\xe7 d\xfcnya ve toplum","D\xfczenli \u0130badetin D\xf6n\xfc\u015ft\xfcrmesi","Dua, namaz ve zikir insan karakterini d\xf6n\xfc\u015ft\xfcr\xfcr.","Pratik sonu\xe7 tek ba\u015f\u0131na metafizik ispat de\u011fildir; fakat hakiki din\xee hayat\u0131n insan\u0131 ar\u0131nd\u0131rmas\u0131, dinin yaln\u0131z psikolojik ka\xe7\u0131\u015f olmad\u0131\u011f\u0131na i\u015faret edebilir.",B.bg_,"orta",B.ai,B.aFN)
