B.ah0=new A.d("DELIL-0180","Biyolojik Deliller","H\xfccre, bilgi ve hayat","Mikrobiyom Delili","\u0130nsan bedeni, faydal\u0131 mikroorganizmalarla ortak ya\u015fam i\xe7indedir.","Sindirim, ba\u011f\u0131\u015f\u0131kl\u0131k ve metabolizma mikrobiyomla ili\u015fkilidir. G\xf6r\xfcnmeyen k\xfc\xe7\xfck canl\u0131lar\u0131n b\xfcy\xfck sa\u011fl\u0131k etkileri, hayat a\u011f\u0131n\u0131n ince ili\u015fkilerini g\xf6sterir.",B.bkV,"orta",B.n,B.ax8)
