B.akM=new A.d("DELIL-0202","Felsefi ve Kel\xe2m\xee Deliller","\u0130nsanl\u0131k tarihinden arg\xfcmanlar","\u0130bn R\xfc\u015fd\u2019\xfcn \u0130nayet ve \u0130htira Delili","Canl\u0131ya uygunluk ve yarat\u0131l\u0131\u015f d\xfczeni Allah\u2019a i\u015faret eder.","\u0130bn R\xfc\u015fd, Kur\u2019an\xee delil olarak inayet ve ihtira hatlar\u0131n\u0131 \xf6ne \xe7\u0131kar\u0131r: evren insan ve canl\u0131l\u0131k i\xe7in uygun, varl\u0131klar yarat\u0131lm\u0131\u015fl\u0131k g\xf6stergesidir.",B.bqs,"orta-y\xfcksek",B.n,B.aI2)
