B.akf=new A.d("DELIL-0370","Astronomi Delilleri","Kullan\u0131c\u0131 ek listesi","D\xfcnya\u2019n\u0131n Manyetik Kalkan\u0131","G\xfcne\u015f r\xfczgarlar\u0131n\u0131 engelleyen g\xf6r\xfcnmez z\u0131rh.","D\xfcnyan\u0131n \xe7ekirde\u011findeki demir ak\u0131\u015f\u0131yla olu\u015fan manyetosfer, \xf6ld\xfcr\xfcc\xfc radyasyonu sapt\u0131r\u0131r. Bu kalkan olmasayd\u0131 atmosfer yok olurdu.",B.n,"orta",B.H,B.aIV)
