B.am4=new A.d("DELIL-0375","Astronomi Delilleri","Kullan\u0131c\u0131 ek listesi","Atmosferin Gaz Kar\u0131\u015f\u0131m\u0131","%21 oksijen; ne eksik ne fazla.","%15 olsa nefes alamay\u0131z, %25 olsa ormanlar en ufak k\u0131v\u0131lc\u0131mla yanar. Bu oran hayat\u0131n devam\u0131 i\xe7in hassas bir dengedir.",B.n,"orta",B.H,B.aFD)
